export class TestCasesController {
  constructor(private readonly testCasesService: TestCasesService) {}

  @Post()
  @Roles(Role.ADMIN, Role.TEST_LEAD, Role.TESTER)
  @ApiOperation({ summary: 'Yeni Test Case ve adımlarını oluştur (Admin, Lead, Tester)' })
  @ApiResponse({ status: 201, description: 'Test Case başarıyla oluşturuldu' })
  create(@Body() createTestCaseDto: CreateTestCaseDto) {
    return this.testCasesService.create(createTestCaseDto);
  }

  @Get()
  @ApiOperation({ summary: 'Bir Suite içindeki tüm Test Case\'leri listele' })
  @ApiQuery({ name: 'suiteId', required: true, description: 'Suite UUID' })
  findAllBySuite(@Query('suiteId') suiteId: string) {
    return this.testCasesService.findAllBySuite(suiteId);
  }

  @Get(':id')
  @ApiOperation({ summary: 'ID ile Test Case detaylarını adımlarıyla getir' })
  @ApiParam({ name: 'id', description: 'TestCase UUID' })
  findOne(@Param('id') id: string) {
    return this.testCasesService.findOne(id);
  }

  @Get('code/:code')
  @ApiOperation({ summary: 'Kod ile Test Case detaylarını getir (Örn: PRJ-TC-1)' })
  @ApiParam({ name: 'code', description: 'Test Case Kodu (PRJ-TC-1)' })
  findByCode(@Param('code') code: string) {
    return this.testCasesService.findByCode(code);
  }

  @Patch(':id/jira-link')
  @Roles(Role.ADMIN, Role.TEST_LEAD, Role.TESTER)
  @ApiOperation({ summary: 'Test Case ile Jira Story ID eşleştir (Admin, Lead, Tester)' })
  @ApiParam({ name: 'id', description: 'TestCase UUID' })
  linkJiraStory(@Param('id') id: string, @Body() dto: LinkJiraStoryDto) {
    return this.testCasesService.linkJiraStory(id, dto.jiraStoryKey, dto.jiraIssueUrl);
  }

  @Patch(':id')
  @Roles(Role.ADMIN, Role.TEST_LEAD, Role.TESTER)
  @ApiOperation({ summary: 'Test Case ve adımlarını güncelle (Admin, Lead, Tester)' })
  @ApiParam({ name: 'id', description: 'TestCase UUID' })
  update(@Param('id') id: string, @Body() updateTestCaseDto: UpdateTestCaseDto) {
    return this.testCasesService.update(id, updateTestCaseDto);
  }

  @Delete(':id')
  @Roles(Role.ADMIN, Role.TEST_LEAD, Role.TESTER)
  @ApiOperation({ summary: 'Test Case\'i sil (Admin, Lead, Tester)' })
  @ApiParam({ name: 'id', description: 'TestCase UUID' })
  remove(@Param('id') id: string) {
    return this.testCasesService.remove(id);
  }
}

export class TestCasesService {
  constructor(private readonly prisma: PrismaService) {}

  async create(createTestCaseDto: CreateTestCaseDto) {
    let projectKey: string;
    let projectId: string;
    let suiteId: string | null = createTestCaseDto.suiteId || null;

    if (suiteId) {
      const suite = await this.prisma.suite.findUnique({
        where: { id: suiteId },
        include: { project: true },
      });

      if (!suite) {
        throw new NotFoundException(`Suite with ID ${suiteId} not found`);
      }

      projectKey = suite.project.key;
      projectId = suite.projectId;
    } else if (createTestCaseDto.projectId) {
      const project = await this.prisma.project.findUnique({
        where: { id: createTestCaseDto.projectId },
      });

      if (!project) {
        throw new NotFoundException(`Project with ID ${createTestCaseDto.projectId} not found`);
      }

      projectKey = project.key;
      projectId = project.id;
    } else {
      throw new NotFoundException('Either suiteId or projectId must be provided to create a Test Case');
    }

    // Find highest test case number for the project to generate unique code
    const existingCases = await this.prisma.testCase.findMany({
      where: {
        OR: [
          { projectId },
          { suite: { projectId } },
        ],
      },
      select: { code: true },
    });

    let maxNumber = 0;
    const prefix = `${projectKey}-TC-`;
    for (const tc of existingCases) {
      if (tc.code.startsWith(prefix)) {
        const num = parseInt(tc.code.substring(prefix.length), 10);
        if (!isNaN(num) && num > maxNumber) {
          maxNumber = num;
        }
      }
    }

    const code = `${projectKey}-TC-${maxNumber + 1}`;

    const { steps, ...caseData } = createTestCaseDto;

    return this.prisma.testCase.create({
      data: {
        ...caseData,
        projectId,
        suiteId: suiteId || undefined,
        code,
        steps: steps && steps.length > 0 ? {
          create: steps.map((step, idx) => ({
            stepNumber: step.stepNumber || idx + 1,
            action: step.action,
            expectedResult: step.expectedResult || '',
            attachments: step.attachments ? JSON.parse(JSON.stringify(step.attachments)) : [],
          })),
        } : undefined,
      },
      include: {
        steps: {
          orderBy: { stepNumber: 'asc' },
        },
      },
    });
  }

  async findAllBySuite(suiteId: string) {
    return this.prisma.testCase.findMany({
      where: { suiteId },
      include: {
        steps: {
          orderBy: { stepNumber: 'asc' },
        },
        results: {
          orderBy: { executedAt: 'desc' },
          take: 1,
        },
      },
      orderBy: { createdAt: 'asc' },
    });
  }

  async findOne(id: string) {
    const testCase = await this.prisma.testCase.findUnique({
      where: { id },
      include: {
        suite: {
          include: {
            project: true,
          },
        },
        steps: {
          orderBy: { stepNumber: 'asc' },
        },
        results: {
          orderBy: { executedAt: 'desc' },
          include: {
            testRun: {
              select: {
                id: true,
                title: true,
                version: true,
                environment: true,
                status: true,
                executedBy: true,
              },
            },
          },
        },
      },
    });

    if (!testCase) {
      throw new NotFoundException(`TestCase with ID ${id} not found`);
    }

    return testCase;
  }

  async findByCode(code: string) {
    const testCase = await this.prisma.testCase.findUnique({
      where: { code },
      include: {
        suite: {
          include: {
            project: true,
          },
        },
        steps: {
          orderBy: { stepNumber: 'asc' },
        },
        results: {
          orderBy: { executedAt: 'desc' },
          include: {
            testRun: {
              select: {
                id: true,
                title: true,
                version: true,
                environment: true,
                status: true,
                executedBy: true,
              },
            },
          },
        },
      },
    });

    if (!testCase) {
      throw new NotFoundException(`TestCase with code ${code} not found`);
    }

    return testCase;
  }

  async update(id: string, updateTestCaseDto: UpdateTestCaseDto) {
    const { steps, ...caseData } = updateTestCaseDto;

    return this.prisma.$transaction(async (tx) => {
      // If steps are provided, replace existing steps
      if (steps) {
        await tx.testStep.deleteMany({
          where: { testCaseId: id },
        });
      }

      return tx.testCase.update({
        where: { id },
        data: {
          ...caseData,
          steps: steps ? {
            create: steps.map((step, idx) => ({
              stepNumber: step.stepNumber || idx + 1,
              action: step.action,
              expectedResult: step.expectedResult || '',
              attachments: step.attachments ? JSON.parse(JSON.stringify(step.attachments)) : [],
            })),
          } : undefined,
        },
        include: {
          steps: {
            orderBy: { stepNumber: 'asc' },
          },
          results: {
            orderBy: { executedAt: 'desc' },
            include: {
              testRun: {
                select: {
                  id: true,
                  title: true,
                  version: true,
                  environment: true,
                  status: true,
                  executedBy: true,
                },
              },
            },
          },
        },
      });
    });
  }


  async linkJiraStory(id: string, jiraStoryKey?: string, jiraIssueUrl?: string) {
    await this.findOne(id);
    const generatedUrl = jiraIssueUrl || (jiraStoryKey ? `https://company.atlassian.net/browse/${jiraStoryKey}` : null);

    return this.prisma.testCase.update({
      where: { id },
      data: {
        jiraStoryKey: jiraStoryKey || null,
        jiraIssueUrl: generatedUrl,
      },
    });
  }

  async remove(id: string) {
    await this.findOne(id);
    return this.prisma.testCase.delete({
      where: { id },
    });
  }
}

