  })
  @IsOptional()
  @IsEnum(ReportExportFormat)
  format?: ReportExportFormat = ReportExportFormat.JSON;

  @ApiPropertyOptional({
    description: 'Optional filter by test run ID',
  })
  @IsOptional()
  @IsString()
  runId?: string;
}

export interface NavigationState {
  tab: 'DASHBOARD' | 'EXPLORER' | 'RUNS' | 'REPORTS';
  projectId: string | null;
  suiteId: string | null;
  caseId: string | null;
  label: string;
  timestamp?: number;
}

interface NavigationContextType {
  history: NavigationState[];
  currentIndex: number;
  currentState: NavigationState | null;
  canGoBack: boolean;
  canGoForward: boolean;
  previousState: NavigationState | null;
  nextState: NavigationState | null;
  pushState: (state: Omit<NavigationState, 'timestamp'>) => void;
  goBack: () => void;
  goForward: () => void;
  registerNavigationHandler: (handler: (state: NavigationState) => void) => () => void;
}

const NavigationContext = createContext<NavigationContextType | undefined>(undefined);

const MAX_HISTORY_LENGTH = 50;

export const NavigationProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [history, setHistory] = useState<NavigationState[]>([]);
  const [currentIndex, setCurrentIndex] = useState<number>(-1);

  // Synchronous refs to prevent any stale closure issues
  const historyRef = useRef<NavigationState[]>([]);
  const currentIndexRef = useRef<number>(-1);
  const isNavigatingRef = useRef(false);
  const navigationHandlerRef = useRef<((state: NavigationState) => void) | null>(null);

  const currentState = currentIndex >= 0 && currentIndex < history.length ? history[currentIndex] : null;

  // canGoBack is true if there is a previous history item OR if we are currently deep in Explorer/Suite/Case/Runs and can navigate back to Dashboard
  const canGoBack =
    currentIndex > 0 ||
    Boolean(currentState && (currentState.tab !== 'DASHBOARD' || currentState.suiteId || currentState.caseId));

  const canGoForward = currentIndex >= 0 && currentIndex < history.length - 1;
  const previousState = currentIndex > 0 ? history[currentIndex - 1] : null;
  const nextState = canGoForward ? history[currentIndex + 1] : null;

  // Load history from localStorage on initial mount
  useEffect(() => {
    try {
      const savedHist = localStorage.getItem('tcms_nav_history');
      const savedIdx = localStorage.getItem('tcms_nav_index');
      if (savedHist && savedIdx !== null) {
        const parsed = JSON.parse(savedHist);
        const idx = parseInt(savedIdx, 10);
        if (Array.isArray(parsed) && parsed.length > 0 && idx >= 0 && idx < parsed.length) {
          historyRef.current = parsed;
          currentIndexRef.current = idx;
          setHistory(parsed);
          setCurrentIndex(idx);
        }
      }
    } catch {
      // Ignore
    }
  }, []);

  const persistNavHistory = (hist: NavigationState[], idx: number) => {
    try {
      localStorage.setItem('tcms_nav_history', JSON.stringify(hist));
      localStorage.setItem('tcms_nav_index', String(idx));
    } catch {
      // Ignore
    }
  };

  // Register state applicator from page.tsx
  const registerNavigationHandler = useCallback((handler: (state: NavigationState) => void) => {
    navigationHandlerRef.current = handler;
    return () => {
      navigationHandlerRef.current = null;
    };
  }, []);

  // Push new navigation state - completely synchronous via refs
  const pushState = useCallback((newState: Omit<NavigationState, 'timestamp'>) => {
    if (isNavigatingRef.current) return;

    const prevHistory = historyRef.current;
    const currentIdx = currentIndexRef.current;
    const currentItem = currentIdx >= 0 && currentIdx < prevHistory.length ? prevHistory[currentIdx] : null;

    // Avoid consecutive duplicate states
    if (
      currentItem &&
      currentItem.tab === newState.tab &&
      currentItem.projectId === newState.projectId &&
      currentItem.suiteId === newState.suiteId &&
      currentItem.caseId === newState.caseId
    ) {
      // If only the label updated (e.g. project name loaded), update current in place
      if (currentItem.label !== newState.label) {
        const updated = [...prevHistory];
        updated[currentIdx] = { ...currentItem, label: newState.label };
        historyRef.current = updated;
        setHistory(updated);
        persistNavHistory(updated, currentIdx);
      }
      return;
    }

    // Truncate any forward history if we were in the middle of the stack
    const validHistory = currentIdx >= 0 ? prevHistory.slice(0, currentIdx + 1) : [];
    const itemWithTime: NavigationState = {
      ...newState,
      timestamp: Date.now(),
    };

    const newHistory = [...validHistory, itemWithTime];
    if (newHistory.length > MAX_HISTORY_LENGTH) {
      newHistory.shift();
    }

    const newIndex = newHistory.length - 1;

    historyRef.current = newHistory;
    currentIndexRef.current = newIndex;

    setHistory(newHistory);
    setCurrentIndex(newIndex);
    persistNavHistory(newHistory, newIndex);
  }, []);

  // Go Back with Smart Fallback
  const goBack = useCallback(() => {
    const prevHistory = historyRef.current;
    const currentIdx = currentIndexRef.current;

    // 1. Standard History Back
    if (currentIdx > 0 && prevHistory.length > 1) {
      const targetIndex = currentIdx - 1;
      const targetState = prevHistory[targetIndex];

      if (targetState) {
        isNavigatingRef.current = true;
        currentIndexRef.current = targetIndex;
        setCurrentIndex(targetIndex);
        persistNavHistory(prevHistory, targetIndex);

        if (navigationHandlerRef.current) {
          navigationHandlerRef.current(targetState);
        }

        setTimeout(() => {
          isNavigatingRef.current = false;
        }, 150);
        return;
      }
    }

    // 2. Smart Contextual Fallback (e.g. after refresh when in Suite, Case, or non-Dashboard tab)
    const current = currentIdx >= 0 && currentIdx < prevHistory.length ? prevHistory[currentIdx] : null;
    if (navigationHandlerRef.current) {
      const fallbackState: NavigationState = {
        tab: 'DASHBOARD',
        projectId: current?.projectId || null,
        suiteId: null,
        caseId: null,
        label: 'Dashboard',
        timestamp: Date.now(),
      };

      isNavigatingRef.current = true;
      navigationHandlerRef.current(fallbackState);

      const updatedHistory = [fallbackState];
      historyRef.current = updatedHistory;
      currentIndexRef.current = 0;
      setHistory(updatedHistory);
      setCurrentIndex(0);
      persistNavHistory(updatedHistory, 0);

      setTimeout(() => {
        isNavigatingRef.current = false;
      }, 150);
    }
  }, []);

  // Go Forward
  const goForward = useCallback(() => {
    const prevHistory = historyRef.current;
    const currentIdx = currentIndexRef.current;

    if (currentIdx >= 0 && currentIdx < prevHistory.length - 1) {
      const targetIndex = currentIdx + 1;
      const targetState = prevHistory[targetIndex];

      if (targetState) {
        isNavigatingRef.current = true;
        currentIndexRef.current = targetIndex;
        setCurrentIndex(targetIndex);
        persistNavHistory(prevHistory, targetIndex);

        if (navigationHandlerRef.current) {
          navigationHandlerRef.current(targetState);
        }

        setTimeout(() => {
          isNavigatingRef.current = false;
        }, 150);
      }
    }
  }, []);

  // Keyboard shortcut listener (Alt + Left Arrow for Back, Alt + Right Arrow for Forward)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement | null;
      const isInput =
        target &&
        (target.tagName === 'INPUT' ||
          target.tagName === 'TEXTAREA' ||
          target.tagName === 'SELECT' ||
          target.isContentEditable);

      if (e.altKey && e.key === 'ArrowLeft') {
        e.preventDefault();
        goBack();
      } else if (e.altKey && e.key === 'ArrowRight') {
        e.preventDefault();
        goForward();
      } else if (e.key === 'Backspace' && !isInput && !e.ctrlKey && !e.metaKey) {
        e.preventDefault();
        goBack();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [goBack, goForward]);

  return (
    <NavigationContext.Provider
      value={{
        history,
        currentIndex,
        currentState,
        canGoBack,
        canGoForward,
        previousState,
        nextState,
        pushState,
        goBack,
        goForward,
        registerNavigationHandler,
      }}
    >
      {children}
    </NavigationContext.Provider>
  );
};

export const useNavigation = () => {
  const context = useContext(NavigationContext);
  if (!context) {
    throw new Error('useNavigation must be used within a NavigationProvider');
  }
  return context;
};

export const ThemeProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [theme, setThemeState] = useState<ThemeId>('crimson-dark');
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
    const savedTheme = localStorage.getItem('tcms_theme') as ThemeId | null;
    if (savedTheme === 'crimson-dark' || savedTheme === 'crimson-light') {
      setThemeState(savedTheme);
    } else {
      setThemeState('crimson-dark');
    }
  }, []);

  useEffect(() => {
    if (!mounted) return;
    const root = document.documentElement;

    // Reset classes & attributes
    root.classList.remove('dark', 'theme-crimson', 'theme-light');
    root.removeAttribute('data-theme');

    root.setAttribute('data-theme', theme);

    if (theme === 'crimson-dark') {
      root.classList.add('dark', 'theme-crimson');
    } else {
      root.classList.add('theme-light');
    }

    localStorage.setItem('tcms_theme', theme);
  }, [theme, mounted]);

  const setTheme = (newTheme: ThemeId) => {
    setThemeState(newTheme);
  };

  const tokens = themePresets[theme] || themePresets['crimson-dark'];
  const availableThemes = Object.values(THEME_METADATA);

  return (
    <ThemeContext.Provider value={{ theme, setTheme, tokens, availableThemes }}>
      {children}
    </ThemeContext.Provider>
  );
};

export const useTheme = () => {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error('useTheme must be used within a ThemeProvider');
  }
  return context;
};

export type PermissionAction =
  | 'MANAGE_USERS'
  | 'CREATE_PROJECT'
  | 'EDIT_PROJECT'
  | 'DELETE_PROJECT'
  | 'CREATE_SUITE'
  | 'EDIT_SUITE'
  | 'DELETE_SUITE'
  | 'CREATE_CASE'
  | 'EDIT_CASE'
  | 'DELETE_CASE'
  | 'EXECUTE_RUN'
  | 'VIEW_REPORTS';

interface AuthSessionData {
  userId: string;
  email: string;
  role: UserRole;
  name: string;
  loginTime: number;
  expiresAt: number;
}

const SESSION_STORAGE_KEY = 'tcms_auth_session';
const SESSION_DURATION_MS = 24 * 60 * 60 * 1000; // 24 Hours

export const STANDARD_PASSWORD = 'password1234';

interface AuthContextType {
  currentUser: User | null;
  users: User[];
  role: UserRole;
  isAuthenticated: boolean;
  isLoading: boolean;
  login: (email: string, password: string) => Promise<{ success: boolean; error?: string }>;
  logout: () => void;
  hasRole: (allowedRoles: UserRole[]) => boolean;
  can: (action: PermissionAction) => boolean;
  refreshUsers: () => Promise<void>;
  isViewer: boolean;
  isAdmin: boolean;
  isTestLead: boolean;
  isTester: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [isLoading, setIsLoading] = useState<boolean>(true);

  // Helper to validate and restore session from localStorage
  const checkAndRestoreSession = useCallback((userList: User[]) => {
    try {
      const rawSession = localStorage.getItem(SESSION_STORAGE_KEY);
      if (!rawSession) {
        setIsAuthenticated(false);
        setCurrentUser(null);
        return false;
      }

      const session: AuthSessionData = JSON.parse(rawSession);
      const now = Date.now();

      // Check 24-hour expiration
      if (!session.expiresAt || now > session.expiresAt) {
        localStorage.removeItem(SESSION_STORAGE_KEY);
        setIsAuthenticated(false);
        setCurrentUser(null);
        return false;
      }

      // Find user in active list
      const matchedUser = userList.find((u) => u.id === session.userId || u.email.toLowerCase() === session.email.toLowerCase());
      if (matchedUser && matchedUser.isActive) {
        setCurrentUser(matchedUser);
        setIsAuthenticated(true);
        return true;
      } else {
        localStorage.removeItem(SESSION_STORAGE_KEY);
        setIsAuthenticated(false);
        setCurrentUser(null);
        return false;
      }
    } catch {
      localStorage.removeItem(SESSION_STORAGE_KEY);
      setIsAuthenticated(false);
      setCurrentUser(null);
      return false;
    }
  }, []);

  // Fetch users and initialize auth state on mount
  const refreshUsers = useCallback(async () => {
    try {
      setIsLoading(true);
      const userList = await UsersService.getUsers();
      setUsers(userList);
      checkAndRestoreSession(userList);
    } catch (err) {
      console.error('Failed to load users for AuthContext:', err);
    } finally {
      setIsLoading(false);
    }
  }, [checkAndRestoreSession]);

  useEffect(() => {
    refreshUsers();
  }, [refreshUsers]);

  // Login handler
  const login = async (email: string, password: string): Promise<{ success: boolean; error?: string }> => {
    if (!email || !email.trim()) {
      return { success: false, error: 'Lütfen e-posta adresinizi giriniz.' };
    }

    if (!password) {
      return { success: false, error: 'Lütfen şifrenizi giriniz.' };
    }

    // Standard password verification
    if (password !== STANDARD_PASSWORD) {
      return { success: false, error: 'Hatalı şifre. Lütfen standart şifreyi (password1234) giriniz.' };
    }

    let activeUsers = users;
    if (activeUsers.length === 0) {
      try {
        activeUsers = await UsersService.getUsers();
        setUsers(activeUsers);
      } catch {
        return { success: false, error: 'Kullanıcı listesi yüklenemedi. Lütfen bağlantınızı kontrol ediniz.' };
      }
    }

    const matchedUser = activeUsers.find(
      (u) => u.email.toLowerCase() === email.trim().toLowerCase()
    );

    if (!matchedUser) {
      return { success: false, error: 'Bu e-posta adresine ait bir kullanıcı bulunamadı.' };
    }

    if (!matchedUser.isActive) {
      return { success: false, error: 'Bu kullanıcı hesabı devre dışı bırakılmıştır. Lütfen sistem yöneticinizle iletişime geçin.' };
    }

    const now = Date.now();
    const sessionData: AuthSessionData = {
      userId: matchedUser.id,
      email: matchedUser.email,
      role: matchedUser.role,
      name: matchedUser.name,
      loginTime: now,
      expiresAt: now + SESSION_DURATION_MS, // 24 Hours
    };

    localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(sessionData));
    localStorage.setItem('tcms_active_user_id', matchedUser.id);
    localStorage.setItem('tcms_active_user_role', matchedUser.role);
    localStorage.setItem('tcms_active_user_email', matchedUser.email);
    localStorage.setItem('tcms_active_user_name', matchedUser.name);

    setCurrentUser(matchedUser);
    setIsAuthenticated(true);

    return { success: true };
  };

  // Logout handler
  const logout = () => {
    localStorage.removeItem(SESSION_STORAGE_KEY);
    localStorage.removeItem('tcms_active_user_id');
    localStorage.removeItem('tcms_active_user_role');
    localStorage.removeItem('tcms_active_user_email');
    localStorage.removeItem('tcms_active_user_name');
    setCurrentUser(null);
    setIsAuthenticated(false);
  };

  const effectiveRole: UserRole = currentUser?.role || 'VIEWER';

  const hasRole = useCallback(
    (allowedRoles: UserRole[]) => {
      return allowedRoles.includes(effectiveRole);
    },
    [effectiveRole],
  );

  const can = useCallback(
    (action: PermissionAction): boolean => {
      if (!isAuthenticated) return false;

      switch (action) {
        case 'MANAGE_USERS':
          return effectiveRole === 'ADMIN';

        case 'CREATE_PROJECT':
        case 'EDIT_PROJECT':
        case 'DELETE_PROJECT':
          return effectiveRole === 'ADMIN' || effectiveRole === 'TEST_LEAD';

        case 'CREATE_SUITE':
        case 'EDIT_SUITE':
          return effectiveRole === 'ADMIN' || effectiveRole === 'TEST_LEAD' || effectiveRole === 'TESTER';

        case 'DELETE_SUITE':
          return effectiveRole === 'ADMIN' || effectiveRole === 'TEST_LEAD';

        case 'CREATE_CASE':
        case 'EDIT_CASE':
        case 'DELETE_CASE':
        case 'EXECUTE_RUN':
          return effectiveRole === 'ADMIN' || effectiveRole === 'TEST_LEAD' || effectiveRole === 'TESTER';

        case 'VIEW_REPORTS':
          return true; // All authenticated roles can view reports

        default:
          return false;
      }
    },
    [effectiveRole, isAuthenticated],
  );

  const isAdmin = effectiveRole === 'ADMIN';
  const isTestLead = effectiveRole === 'TEST_LEAD';
  const isTester = effectiveRole === 'TESTER';
  const isViewer = effectiveRole === 'VIEWER';

  return (
    <AuthContext.Provider
      value={{
        currentUser,
        users,
        role: effectiveRole,
        isAuthenticated,
        isLoading,
        login,
        logout,
        hasRole,
        can,
        refreshUsers,
        isViewer,
        isAdmin,
        isTestLead,
        isTester,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

