                  >
                    <option value="ALL">Tüm Durumlar</option>
                    <option value="PASSED">Geçti (PASSED)</option>
                    <option value="FAILED">Kaldı (FAILED)</option>
                    <option value="BLOCKED">Bloke (BLOCKED)</option>
                    <option value="UNTESTED">Koşulmamış</option>
