              ))}

              {(summary?.failedCases || []).length === 0 && (
                <div className="col-span-2 p-12 text-center text-slate-400 bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800">
                  <CheckCircle2 className="w-10 h-10 text-emerald-500 mx-auto mb-2 opacity-80" />
                  <p className="font-medium text-slate-700 dark:text-slate-300">Harika! Başarısız veya hata alan test senaryosu bulunmuyor.</p>
                </div>
              )}
            </div>
          </div>
        )}

        {/* 4. SUB-TAB: MODÜL / SUITE KAPSAMI */}
        {activeSubTab === 'SUITES' && (
          <div className="space-y-4">
            <h3 className="text-sm font-bold text-slate-900 dark:text-white flex items-center gap-2">
              <Layers className="w-4 h-4 text-rose-500" />
              <span>Modül & Suite Başarı Performans Matrisi</span>
            </h3>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {(summary?.suites || []).map((suite) => (
                <div
                  key={suite.id}
                  className="p-4 rounded-xl bg-white dark:bg-slate-900/90 border border-slate-200 dark:border-slate-800 shadow-sm space-y-3"
                >
                  <div className="flex items-center justify-between">
                    <h4 className="text-xs font-bold text-slate-900 dark:text-white truncate">{suite.name}</h4>
                    <span className="text-xs font-mono font-bold text-slate-500">{suite.totalCases} Test</span>
                  </div>

                  {/* Progress Bar */}
                  <div className="space-y-1">
                    <div className="flex items-center justify-between text-[11px] font-semibold">
                      <span className="text-slate-500">Başarı Oranı</span>
                      <span className={suite.passRate >= 75 ? 'text-emerald-500' : 'text-rose-500'}>%{suite.passRate}</span>
                    </div>
                    <div className="h-2 rounded-full bg-slate-100 dark:bg-slate-800 overflow-hidden flex">
                      <div style={{ width: `${suite.passRate}%` }} className="bg-emerald-500 h-full" />
                      <div style={{ width: `${(suite.failed / (suite.totalCases || 1)) * 100}%` }} className="bg-rose-500 h-full" />
                    </div>
                  </div>

                  <div className="flex items-center justify-between text-[11px] text-slate-500 pt-1 border-t border-slate-100 dark:border-slate-800">
                    <span className="text-emerald-600 dark:text-emerald-400">✓ {suite.passed} Geçti</span>
                    <span className="text-rose-600 dark:text-rose-400">✕ {suite.failed} Kaldı</span>
                    <span className="text-slate-400">○ {suite.untested} Bekliyor</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export const UserManagementModal: React.FC<UserManagementModalProps> = ({
  isOpen,
  onClose,
}) => {
  const { users, currentUser, refreshUsers, isAdmin } = useAuth();
  const [activeTab, setActiveTab] = useState<'LIST' | 'CREATE'>('LIST');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  // Form State
  const [formData, setFormData] = useState<CreateUserInput>({
    name: '',
    email: '',
    role: 'TESTER',
    department: 'Kalite Güvence / QA',
    avatarUrl: '',
  });

  if (!isOpen || !isAdmin) return null;

  const showNotification = (type: 'SUCCESS' | 'ERROR', msg: string) => {
    if (type === 'SUCCESS') {
      setSuccessMsg(msg);
      setErrorMsg(null);
      setTimeout(() => setSuccessMsg(null), 3500);
    } else {
      setErrorMsg(msg);
      setSuccessMsg(null);
      setTimeout(() => setErrorMsg(null), 4500);
    }
  };

  const handleRoleChange = async (userId: string, newRole: UserRole) => {
    try {
      await UsersService.updateUser(userId, { role: newRole });
      await refreshUsers();
      showNotification('SUCCESS', 'Kullanıcı rolü başarıyla güncellendi.');
    } catch (err: any) {
      showNotification('ERROR', err.response?.data?.message || 'Rol güncellenirken hata oluştu.');
    }
  };

  const handleToggleStatus = async (user: User) => {
    try {
      await UsersService.updateUser(user.id, { isActive: !user.isActive });
      await refreshUsers();
      showNotification(
        'SUCCESS',
        `Kullanıcı ${!user.isActive ? 'aktif edildi' : 'pasifleştirildi'}.`,
      );
    } catch (err: any) {
      showNotification('ERROR', err.response?.data?.message || 'Durum değiştirilemedi.');
    }
  };

  const handleDeleteUser = async (user: User) => {
    if (user.id === currentUser?.id) {
      alert('Kendi hesabınızı silemezsiniz.');
      return;
    }
    if (!confirm(`'${user.name}' adlı kullanıcıyı silmek istediğinize emin misiniz?`)) {
      return;
    }
    try {
      await UsersService.deleteUser(user.id);
      await refreshUsers();
      showNotification('SUCCESS', 'Kullanıcı sistemden silindi.');
    } catch (err: any) {
      showNotification('ERROR', err.response?.data?.message || 'Kullanıcı silinemedi.');
    }
  };

  const handleCreateSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name.trim() || !formData.email.trim()) {
      showNotification('ERROR', 'Lütfen ad-soyad ve e-posta alanlarını doldurun.');
      return;
    }

    try {
      setIsSubmitting(true);
      await UsersService.createUser({
        name: formData.name.trim(),
        email: formData.email.trim().toLowerCase(),
        role: formData.role,
        department: formData.department?.trim() || undefined,
        avatarUrl: formData.avatarUrl?.trim() || undefined,
      });
      await refreshUsers();
      showNotification('SUCCESS', 'Yeni kullanıcı başarıyla oluşturuldu.');
      setFormData({
        name: '',
        email: '',
        role: 'TESTER',
        department: 'Kalite Güvence / QA',
        avatarUrl: '',
      });
      setActiveTab('LIST');
    } catch (err: any) {
      showNotification('ERROR', err.response?.data?.message || 'Kullanıcı oluşturulurken bir hata oluştu.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const getRoleBadgeStyle = (role: UserRole) => {
    switch (role) {
      case 'ADMIN':
        return 'bg-[#b83a4b]/15 text-[#b83a4b] dark:text-[#d66b7a] border-[#b83a4b]/30';
      case 'TEST_LEAD':
        return 'bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 border-indigo-500/30';
      case 'TESTER':
        return 'bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border-emerald-500/30';
      case 'VIEWER':
        return 'bg-slate-500/15 text-slate-600 dark:text-slate-400 border-slate-500/30';
      default:
        return 'bg-slate-500/15 text-slate-400 border-slate-500/30';
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 backdrop-blur-md p-4 animate-in fade-in duration-200">
      <div className="bg-white dark:bg-[#1a2130] border border-slate-200 dark:border-slate-800 rounded-2xl w-full max-w-4xl max-h-[85vh] flex flex-col shadow-2xl overflow-hidden animate-in zoom-in-95 duration-150">
        {/* Header */}
        <div className="p-4 sm:p-5 border-b border-slate-200 dark:border-slate-800/80 flex items-center justify-between bg-slate-50/50 dark:bg-slate-900/40">
          <div className="flex items-center space-x-3">
            <div className="w-10 h-10 rounded-xl bg-[#b83a4b]/15 border border-[#b83a4b]/30 flex items-center justify-center text-[#b83a4b] dark:text-[#d66b7a] shrink-0">
              <Users className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-base sm:text-lg font-bold text-slate-900 dark:text-slate-100 flex items-center space-x-2">
                <span>Kullanıcı & Rol Yönetimi (RBAC)</span>
                <span className="text-[10px] font-mono font-bold px-2 py-0.5 rounded-full bg-[#b83a4b]/20 text-[#b83a4b] dark:text-[#d66b7a] border border-[#b83a4b]/30">
                  Faz 1
                </span>
              </h2>
              <p className="text-xs text-slate-500 dark:text-slate-400">
                Sistem kullanıcılarını, erişim seviyelerini ve yetki rollerini yönetin.
              </p>
            </div>
          </div>

          <button
            onClick={onClose}
            className="p-1.5 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Tab Navigation */}
        <div className="px-5 pt-3 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <button
              onClick={() => setActiveTab('LIST')}
              className={`flex items-center space-x-2 pb-2.5 px-3 text-xs font-semibold border-b-2 transition-all ${
                activeTab === 'LIST'
                  ? 'border-[#b83a4b] text-[#b83a4b] dark:text-[#d66b7a]'
                  : 'border-transparent text-slate-500 hover:text-slate-800 dark:hover:text-slate-200'
              }`}
            >
              <Users className="w-4 h-4" />
              <span>Kullanıcı Listesi ({users.length})</span>
            </button>
            <button
              onClick={() => setActiveTab('CREATE')}
              className={`flex items-center space-x-2 pb-2.5 px-3 text-xs font-semibold border-b-2 transition-all ${
                activeTab === 'CREATE'
                  ? 'border-[#b83a4b] text-[#b83a4b] dark:text-[#d66b7a]'
                  : 'border-transparent text-slate-500 hover:text-slate-800 dark:hover:text-slate-200'
              }`}
            >
              <UserPlus className="w-4 h-4" />
              <span>Yeni Kullanıcı Ekle</span>
            </button>
          </div>
        </div>

        {/* Toast / Notification Banner */}
        {successMsg && (
          <div className="mx-5 mt-3 p-2.5 bg-emerald-500/10 border border-emerald-500/30 text-emerald-600 dark:text-emerald-400 rounded-xl flex items-center space-x-2 text-xs animate-in fade-in">
            <CheckCircle2 className="w-4 h-4 shrink-0" />
            <span>{successMsg}</span>
          </div>
        )}
        {errorMsg && (
          <div className="mx-5 mt-3 p-2.5 bg-[#b83a4b]/10 border border-[#b83a4b]/30 text-rose-300 rounded-xl flex items-center space-x-2 text-xs animate-in fade-in">
            <AlertCircle className="w-4 h-4 shrink-0" />
            <span>{errorMsg}</span>
          </div>
        )}

        {/* Body Content */}
        <div className="p-5 flex-1 overflow-y-auto">
          {activeTab === 'LIST' ? (
            <div className="space-y-2">
              {users.map((u) => {
                const isMe = u.id === currentUser?.id;
                return (
                  <div
                    key={u.id}
                    className="p-3 sm:p-4 rounded-xl border border-slate-200 dark:border-slate-800/80 bg-slate-50/60 dark:bg-slate-900/40 hover:bg-slate-100/60 dark:hover:bg-slate-800/40 transition-colors flex flex-col sm:flex-row sm:items-center justify-between gap-3"
                  >
                    {/* User Info */}
                    <div className="flex items-center space-x-3 min-w-0">
                      {u.avatarUrl ? (
                        <img
                          src={u.avatarUrl}
                          alt={u.name}
                          className="w-10 h-10 rounded-full object-cover border border-slate-200 dark:border-slate-700 shrink-0"
                        />
                      ) : (
                        <div className="w-10 h-10 rounded-full bg-slate-200 dark:bg-slate-800 flex items-center justify-center text-slate-600 dark:text-slate-300 font-bold text-sm shrink-0">
                          {u.name.charAt(0)}
                        </div>
                      )}

                      <div className="min-w-0">
                        <div className="flex items-center space-x-2">
                          <span className="font-semibold text-sm text-slate-900 dark:text-slate-100 truncate">
                            {u.name}
                          </span>
                          {isMe && (
                            <span className="text-[9px] font-mono font-bold px-1.5 py-0.2 rounded bg-[#b83a4b]/20 text-[#b83a4b] dark:text-[#d66b7a] border border-[#b83a4b]/30">
                              BEN
                            </span>
                          )}
                          {!u.isActive && (
                            <span className="text-[9px] font-mono px-1.5 py-0.2 rounded bg-slate-200 dark:bg-slate-800 text-slate-500">
                              PASİF
                            </span>
                          )}
                        </div>
                        <p className="text-[11px] text-slate-500 dark:text-slate-400 truncate flex items-center space-x-1.5 mt-0.5">
                          <span>{u.email}</span>
                          {u.department && (
                            <>
                              <span>•</span>
                              <span className="truncate">{u.department}</span>
                            </>
                          )}
                        </p>
                      </div>
                    </div>

                    {/* Role Selector & Actions */}
                    <div className="flex items-center space-x-2.5 shrink-0 self-end sm:self-center">
                      <div className="flex items-center space-x-1.5">
                        <select
                          value={u.role}
                          onChange={(e) => handleRoleChange(u.id, e.target.value as UserRole)}
                          className={`text-xs font-bold font-mono px-2.5 py-1.5 rounded-xl border focus:outline-none focus:ring-1 focus:ring-[#b83a4b] cursor-pointer ${getRoleBadgeStyle(
                            u.role,
                          )} bg-white dark:bg-slate-900`}
                        >
                          <option value="ADMIN">ADMIN</option>
                          <option value="TEST_LEAD">TEST_LEAD</option>
                          <option value="TESTER">TESTER</option>
                          <option value="VIEWER">VIEWER</option>
                        </select>
                      </div>

                      {/* Toggle Active/Inactive */}
                      <button
                        type="button"
                        onClick={() => handleToggleStatus(u)}
                        disabled={isMe}
                        className={`p-1.5 rounded-xl border text-xs transition-colors ${
                          u.isActive
                            ? 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/20 hover:bg-emerald-500/20'
                            : 'bg-slate-200 dark:bg-slate-800 text-slate-500 border-slate-300 dark:border-slate-700 hover:bg-slate-300'
                        } ${isMe ? 'opacity-40 cursor-not-allowed' : ''}`}
                        title={u.isActive ? 'Hesabı Pasifleştir' : 'Hesabı Aktifleştir'}
                      >
                        {u.isActive ? <UserCheck className="w-4 h-4" /> : <UserX className="w-4 h-4" />}
                      </button>

                      {/* Delete */}
                      <button
                        type="button"
                        onClick={() => handleDeleteUser(u)}
                        disabled={isMe}
                        className={`p-1.5 rounded-xl bg-[#b83a4b]/10 text-[#b83a4b] dark:text-[#d66b7a] border border-[#b83a4b]/20 hover:bg-[#b83a4b]/20 transition-colors ${
                          isMe ? 'opacity-40 cursor-not-allowed' : ''
                        }`}
                        title="Kullanıcıyı Sil"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          ) : (
            <form onSubmit={handleCreateSubmit} className="space-y-4 max-w-xl mx-auto">
              <div className="space-y-1.5">
                <label className="block text-xs font-semibold text-slate-700 dark:text-slate-300">
                  Ad ve Soyad <span className="text-[#b83a4b]">*</span>
                </label>
                <div className="relative">
                  <UserIcon className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
                  <input
                    type="text"
                    required
                    placeholder="Örn: Ahmet Yılmaz"
                    value={formData.name}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl text-xs pl-9 pr-3 py-2.5 focus:outline-none focus:ring-1 focus:ring-[#b83a4b]"
                  />
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="block text-xs font-semibold text-slate-700 dark:text-slate-300">
                  E-Posta Adresi <span className="text-[#b83a4b]">*</span>
                </label>
                <div className="relative">
                  <Mail className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
                  <input
                    type="email"
                    required
                    placeholder="ahmet.yilmaz@ttb.com.tr"
                    value={formData.email}
                    onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                    className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl text-xs pl-9 pr-3 py-2.5 focus:outline-none focus:ring-1 focus:ring-[#b83a4b]"
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div className="space-y-1.5">
                  <label className="block text-xs font-semibold text-slate-700 dark:text-slate-300">
                    Kullanıcı Rolü <span className="text-[#b83a4b]">*</span>
                  </label>
                  <select
                    value={formData.role}
                    onChange={(e) => setFormData({ ...formData, role: e.target.value as UserRole })}
                    className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl text-xs px-3 py-2.5 focus:outline-none focus:ring-1 focus:ring-[#b83a4b] font-medium"
                  >
                    <option value="ADMIN">ADMIN (Sistem Yöneticisi)</option>
                    <option value="TEST_LEAD">TEST_LEAD (Test Lideri)</option>
                    <option value="TESTER">TESTER (Test Uzmanı)</option>
                    <option value="VIEWER">VIEWER (Gözlemci / Salt Okunur)</option>
                  </select>
                </div>

                <div className="space-y-1.5">
                  <label className="block text-xs font-semibold text-slate-700 dark:text-slate-300">
                    Departman / Birim
                  </label>
                  <div className="relative">
                    <Briefcase className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
                    <input
                      type="text"
                      placeholder="Örn: Dijital Bankacılık QA"
                      value={formData.department}
                      onChange={(e) => setFormData({ ...formData, department: e.target.value })}
                      className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl text-xs pl-9 pr-3 py-2.5 focus:outline-none focus:ring-1 focus:ring-[#b83a4b]"
                    />
                  </div>
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="block text-xs font-semibold text-slate-700 dark:text-slate-300">
                  Avatar / Fotoğraf URL (İsteğe bağlı)
                </label>
                <input
                  type="url"
                  placeholder="https://..."
                  value={formData.avatarUrl}
                  onChange={(e) => setFormData({ ...formData, avatarUrl: e.target.value })}
                  className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl text-xs px-3 py-2.5 focus:outline-none focus:ring-1 focus:ring-[#b83a4b]"
                />
              </div>

              <div className="pt-3 flex items-center justify-end space-x-2">
                <button
                  type="button"
                  onClick={() => setActiveTab('LIST')}
                  className="px-4 py-2 text-xs font-semibold rounded-xl border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                >
                  İptal
                </button>
                <button
                  type="submit"
                  disabled={isSubmitting}
                  className="px-5 py-2 text-xs font-semibold bg-gradient-to-r from-[#b83a4b] to-[#821c2b] hover:from-[#c54859] hover:to-[#962534] text-white rounded-xl shadow-md shadow-[#821c2b]/20 active:scale-95 transition-all disabled:opacity-50"
                >
                  {isSubmitting ? 'Kaydediliyor...' : 'Kullanıcıyı Kaydet'}
                </button>
              </div>
            </form>
          )}
        </div>

        {/* Footer / Role Legend */}
        <div className="p-3 sm:px-5 border-t border-slate-200 dark:border-slate-800/80 bg-slate-50/50 dark:bg-slate-900/50 flex flex-wrap items-center justify-between gap-2 text-[11px] text-slate-500 dark:text-slate-400">
          <div className="flex flex-wrap items-center gap-2">
            <span className="font-semibold">Rol İzinleri:</span>
            <span className="px-1.5 py-0.5 rounded bg-[#b83a4b]/10 text-[#b83a4b] dark:text-[#d66b7a] font-mono font-bold text-[10px]">
              ADMIN: Tam Yetki + Kullanıcı Yönetimi
            </span>
            <span className="px-1.5 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 font-mono font-bold text-[10px]">
              TEST_LEAD: Plan/Suite/Case/Koşu Yönetimi
            </span>
            <span className="px-1.5 py-0.5 rounded bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 font-mono font-bold text-[10px]">
              TESTER: Case Ekleme & Koşma
            </span>
            <span className="px-1.5 py-0.5 rounded bg-slate-500/10 text-slate-600 dark:text-slate-400 font-mono font-bold text-[10px]">
              VIEWER: Salt Okunur
            </span>
          </div>
          <button
            onClick={onClose}
            className="px-3 py-1 bg-slate-200 dark:bg-slate-800 hover:bg-slate-300 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 rounded-lg text-xs font-semibold transition-colors"
          >
            Kapat
          </button>
        </div>
      </div>
    </div>
  );
};

export const EditProjectModal: React.FC<EditProjectModalProps> = ({
  isOpen,
  onClose,
  project,
  onUpdate,
  onDelete,
}) => {
  const [name, setName] = useState('');
  const [key, setKey] = useState('');
  const [description, setDescription] = useState('');
  const [jiraProjectKey, setJiraProjectKey] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');

  useEffect(() => {
    if (project) {
      setName(project.name || '');
      setKey(project.key || '');
      setDescription(project.description || '');
      setJiraProjectKey(project.jiraProjectKey || '');
      setShowDeleteConfirm(false);
      setErrorMsg('');
    }
  }, [project, isOpen]);

  if (!isOpen || !project) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim() || !key.trim()) return;

    setIsSubmitting(true);
    setErrorMsg('');
    try {
      await onUpdate(project.id, {
        name: name.trim(),
        key: key.trim().toUpperCase(),
        description: description.trim() || undefined,
        jiraProjectKey: jiraProjectKey.trim().toUpperCase() || undefined,
      });
      onClose();
    } catch (err: any) {
      console.error(err);
      const message = err?.response?.data?.message || err?.message || 'Test Planı güncellenirken bir hata oluştu.';
      setErrorMsg(Array.isArray(message) ? message.join(', ') : message);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDelete = async () => {
    setIsDeleting(true);
    setErrorMsg('');
    try {
      await onDelete(project.id);
      onClose();
    } catch (err: any) {
      console.error(err);
      const message = err?.response?.data?.message || err?.message || 'Test Planı silinirken bir hata oluştu.';
      setErrorMsg(Array.isArray(message) ? message.join(', ') : message);
    } finally {
      setIsDeleting(false);
      setShowDeleteConfirm(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl w-full max-w-md shadow-2xl overflow-hidden animate-scaleUp text-slate-800 dark:text-slate-100">
        <div className="px-6 py-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-900/80">
          <div className="flex items-center space-x-2.5">
            <FolderKanban className="w-5 h-5 text-[#b83a4b]" />
            <div>
              <h3 className="text-sm font-bold text-slate-800 dark:text-slate-100">Test Planını Düzenle</h3>
              <p className="text-[11px] text-slate-500 dark:text-slate-400">[{project.key}] {project.name}</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="text-slate-400 hover:text-slate-700 dark:hover:text-white p-1 rounded-lg transition-colors"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {errorMsg && (
          <div className="mx-6 mt-4 p-3 bg-[#b83a4b]/10 border border-[#b83a4b]/30 rounded-xl text-xs text-rose-300 font-medium">
            {errorMsg}
          </div>
        )}

        {showDeleteConfirm ? (
          <div className="p-6 space-y-4">
            <div className="p-4 bg-red-500/10 border border-red-500/30 rounded-xl space-y-2">
              <div className="flex items-center space-x-2 text-red-600 dark:text-red-400 font-bold text-xs">
                <AlertTriangle className="w-4 h-4 shrink-0" />
                <span>Test Planı Silme Onayı</span>
              </div>
              <p className="text-xs text-slate-600 dark:text-slate-300 leading-relaxed">
                <strong>"{project.name}"</strong> test planını ve altındaki tüm Suite, Test Case ve Test Koşusu kayıtlarını silmek istediğinize emin misiniz? Bu işlem geri alınamaz!
              </p>
            </div>

            <div className="flex items-center justify-end space-x-3 pt-2">
              <button
                type="button"
                onClick={() => setShowDeleteConfirm(false)}
                disabled={isDeleting}
                className="px-4 py-2 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 text-xs font-semibold rounded-xl border border-slate-200 dark:border-slate-700"
              >
                Vazgeç
              </button>
              <button
                type="button"
                onClick={handleDelete}
                disabled={isDeleting}
                className="flex items-center space-x-1.5 px-4 py-2 bg-red-600 hover:bg-red-500 text-white text-xs font-bold rounded-xl shadow-lg shadow-red-600/20 disabled:opacity-50"
              >
                <Trash2 className="w-4 h-4" />
                <span>{isDeleting ? 'Siliniyor...' : 'Evet, Planı Tamamen Sil'}</span>
              </button>
            </div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-4">
            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-slate-700 dark:text-slate-300">Test Planı Adı</label>
              <input
                type="text"
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl px-3.5 py-2 text-xs text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-1 focus:ring-[#b83a4b] shadow-sm"
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-slate-700 dark:text-slate-300">
                  Plan Kodu / Key
                </label>
                <input
                  type="text"
                  required
                  maxLength={10}
                  value={key}
                  onChange={(e) => setKey(e.target.value.toUpperCase())}
                  className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl px-3.5 py-2 text-xs font-mono font-bold text-[#b83a4b] dark:text-[#d66b7a] focus:outline-none focus:ring-1 focus:ring-[#b83a4b] uppercase shadow-sm"
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-slate-700 dark:text-slate-300">
                  Jira Proje Kodu
                </label>
                <input
                  type="text"
                  maxLength={10}
                  placeholder="Örn: MOB veya PRJ"
                  value={jiraProjectKey}
                  onChange={(e) => setJiraProjectKey(e.target.value.toUpperCase())}
                  className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl px-3.5 py-2 text-xs font-mono font-bold text-blue-600 dark:text-blue-400 focus:outline-none focus:ring-1 focus:ring-blue-500 uppercase shadow-sm"
                />
