      </div>
    </div>
  );
};

export const ThemeSelector: React.FC = () => {
  const { theme, setTheme, availableThemes } = useTheme();
  const [isOpen, setIsOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  // Close menu when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const getThemeIcon = (id: ThemeId) => {
    switch (id) {
      case 'crimson-light':
        return (
          <Sun className="w-4 h-4 text-amber-500 transition-transform duration-200 group-hover:rotate-45" />
        );
      case 'crimson-dark':
      default:
        return (
          <Moon className="w-4 h-4 text-[#b83a4b] dark:text-[#d66b7a] transition-transform duration-200 group-hover:-rotate-12" />
        );
    }
  };

  const activeThemeMeta = availableThemes.find((t) => t.id === theme) || availableThemes[0];

  return (
    <div className="relative inline-block text-left z-[100]" ref={menuRef}>
      {/* Theme Trigger Button - Compact Icon View */}
      <button
        type="button"
        onClick={() => setIsOpen((prev) => !prev)}
        className="group w-8 sm:w-9 h-8 sm:h-9 flex items-center justify-center rounded-xl bg-slate-100/90 dark:bg-slate-800/80 hover:bg-slate-200/80 dark:hover:bg-slate-700/80 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 transition-all shadow-sm focus:outline-none focus:ring-2 focus:ring-[#b83a4b]/40 cursor-pointer shrink-0"
        title={`Tema Seçici: ${activeThemeMeta.name}`}
        aria-label="Tema Seçici"
      >
        {getThemeIcon(theme)}
      </button>

      {/* Dropdown Menu */}
      {isOpen && (
        <div className="absolute right-0 mt-2 w-72 sm:w-80 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 shadow-2xl drop-shadow-2xl backdrop-blur-xl p-2 animate-in fade-in zoom-in-95 duration-150 z-[100]">
          <div className="px-3 py-2 border-b border-slate-100 dark:border-slate-800/80 flex items-center justify-between">
            <div className="flex items-center space-x-2">
              <Palette className="w-4 h-4 text-[#b83a4b]" />
              <span className="text-xs font-bold text-slate-800 dark:text-slate-200 uppercase tracking-wider">
                Tema Tercihi
              </span>
            </div>
            <span className="text-[10px] text-[#b83a4b] dark:text-[#d66b7a] font-mono font-semibold">Kurumsal Kırmızı</span>
          </div>

          <div className="mt-1 space-y-1">
            {availableThemes.map((t) => {
              const isSelected = t.id === theme;
              return (
                <button
                  key={t.id}
                  onClick={() => {
                    setTheme(t.id);
                    setIsOpen(false);
                  }}
                  className={`w-full text-left px-3 py-2 rounded-xl flex items-center justify-between transition-all ${
                    isSelected
                      ? 'bg-[#b83a4b]/10 dark:bg-[#b83a4b]/15 border border-[#b83a4b]/30 text-slate-900 dark:text-white'
                      : 'hover:bg-slate-100 dark:hover:bg-slate-800/60 text-slate-600 dark:text-slate-300 border border-transparent'
                  }`}
                >
                  <div className="flex items-center space-x-3">
                    <div className="p-1.5 rounded-lg bg-slate-100 dark:bg-slate-800">
                      {getThemeIcon(t.id)}
                    </div>
                    <div>
                      <div className="flex items-center space-x-2">
                        <span className="text-xs font-semibold">{t.name}</span>
                      </div>
                      <p className="text-[10px] text-slate-500 dark:text-slate-400 mt-0.5 line-clamp-1">
                        {t.description}
                      </p>
                    </div>
                  </div>

                  <div className="flex items-center space-x-2">
                    <div className="flex -space-x-1">
                      {t.swatchColors.map((color, idx) => (
                        <span
                          key={idx}
                          className="w-3 h-3 rounded-full border border-black/20 dark:border-white/20 shadow-sm"
                          style={{ backgroundColor: color }}
                        />
                      ))}
                    </div>
                    {isSelected && <Check className="w-4 h-4 text-[#b83a4b] flex-shrink-0" />}
                  </div>
                </button>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
};

export interface TTBLogoProps {
  variant?: 'full' | 'horizontal' | 'emblem' | 'compact';
  height?: number;
  className?: string;
  showSubtitle?: boolean;
  subtitleText?: string;
  colorMode?: 'auto' | 'original' | 'coral' | 'white' | 'slate';
}

/**
 * TTBLogo - Official Türk Ticaret Bankası Brand Logo Component
 * Seamlessly adapts according to the active theme ('crimson-dark' | 'crimson-light').
 */

export const TTBLogo: React.FC<TTBLogoProps> = ({
  variant = 'horizontal',
  height = 36,
  className = '',
  showSubtitle = true,
  subtitleText = 'Test Yönetim Sistemi',
  colorMode = 'auto',
}) => {
  const { theme } = useTheme();
  const isDark = theme === 'crimson-dark';

  // Determine asset paths based on theme & colorMode
  const getEmblemSrc = () => {
    if (colorMode === 'original') return '/brand/ttb-emblem-red.png';
    if (colorMode === 'coral') return '/brand/ttb-emblem-coral.png';
    if (colorMode === 'white') return '/brand/ttb-emblem-white.png';
    if (colorMode === 'slate') return '/brand/ttb-emblem-slate.png';
    // Auto Mode: Official Corporate Red Emblem
    return '/brand/ttb-emblem-red.png';
  };

  const getTextSrc = () => {
    if (colorMode === 'original') return '/brand/ttb-text-red.png';
    if (colorMode === 'coral') return '/brand/ttb-text-coral.png';
    if (colorMode === 'white') return '/brand/ttb-text-white.png';
    if (colorMode === 'slate') return '/brand/ttb-text-slate.png';
    // Auto Mode: In dark mode, crisp white typography stands out cleanly; in light mode, brand red
    return isDark ? '/brand/ttb-text-white.png' : '/brand/ttb-text-red.png';
  };

  // Emblem Only Variant
  if (variant === 'emblem') {
    return (
      <div
        className={`inline-flex items-center justify-center relative select-none transition-transform duration-200 hover:scale-105 ${className}`}
        style={{ height: `${height}px`, width: `${Math.round(height * 1.27)}px` }}
      >
        <img
          src={getEmblemSrc()}
          alt="Türk Ticaret Bankası Amblem"
          className="h-full w-auto object-contain drop-shadow-sm filter transition-all duration-200"
          style={{ maxHeight: `${height}px` }}
        />
      </div>
    );
  }

  // Full Horizontal Brand Logo (Emblem + Typography + TCMS Subtitle)
  if (variant === 'horizontal' || variant === 'full') {
    return (
      <div className={`inline-flex items-center space-x-2.5 sm:space-x-3 select-none ${className}`}>
        {/* Emblem with subtle background sheen */}
        <div
          className="relative shrink-0 flex items-center justify-center transition-transform duration-200 group-hover:scale-105"
          style={{ height: `${height}px`, width: `${Math.round(height * 1.25)}px` }}
        >
          <img
            src={getEmblemSrc()}
            alt="Türk Ticaret Bankası"
            className="h-full w-auto object-contain transition-all duration-200 drop-shadow-sm"
            style={{ maxHeight: `${height}px` }}
          />
        </div>

        {/* Separator / Typography & Subtitle */}
        <div className="flex flex-col justify-center shrink-0">
          <div
            className="relative"
            style={{ height: `${Math.round(height * 0.72)}px` }}
          >
            <img
              src={getTextSrc()}
              alt="Türk Ticaret Bankası"
              className="h-full w-auto object-contain transition-all duration-200"
              style={{ maxHeight: `${Math.round(height * 0.72)}px` }}
            />
          </div>

          {showSubtitle && (
            <div className="flex items-center space-x-1.5 mt-0.5">
              <span className="text-[9px] sm:text-[10px] font-bold tracking-wider uppercase px-1.5 py-0.2 bg-[#b83a4b]/15 text-[#b83a4b] dark:text-[#d66b7a] rounded border border-[#b83a4b]/25 font-mono leading-tight">
                TCMS
              </span>
              <span className="text-[10px] text-slate-500 dark:text-slate-400 font-mono hidden sm:inline leading-tight">
                {subtitleText}
              </span>
            </div>
          )}
        </div>
      </div>
    );
  }

  // Compact Variant (Emblem + Stylized TCMS header)
  return (
    <div className={`flex items-center space-x-2.5 select-none ${className}`}>
      <div
        className="relative shrink-0 rounded-xl p-1 bg-[#b83a4b]/10 border border-[#b83a4b]/20 shadow-sm flex items-center justify-center transition-transform duration-200 group-hover:scale-105"
        style={{ height: `${height}px`, width: `${height}px` }}
      >
        <img
          src={getEmblemSrc()}
          alt="Türk Ticaret Bankası Logo"
          className="h-full w-auto object-contain transition-all duration-200 drop-shadow-sm"
          style={{ maxHeight: `${Math.round(height * 0.85)}px` }}
        />
      </div>

      <div className="flex flex-col justify-center">
        <div className="flex items-center space-x-1.5">
          <span className="text-base font-extrabold tracking-tight bg-gradient-to-r from-slate-950 via-slate-800 to-slate-700 dark:from-white dark:via-slate-100 dark:to-slate-300 bg-clip-text text-transparent leading-none">
            TCMS
          </span>
          <span className="text-[9px] font-bold px-1.5 py-0.5 rounded bg-[#b83a4b]/15 text-[#b83a4b] dark:text-[#d66b7a] border border-[#b83a4b]/25 uppercase tracking-wide leading-none font-mono">
            TTB
          </span>
        </div>
        {showSubtitle && (
          <span className="text-[10px] text-slate-500 dark:text-slate-400 font-medium block mt-0.5 leading-none">
            Türk Ticaret Bankası
          </span>
        )}
      </div>
    </div>
  );
};

export const NewSuiteModal: React.FC<NewSuiteModalProps> = ({
  isOpen,
  onClose,
  projectId,
  projectName,
  projectKey,
  parentSuiteId,
  suites,
  onSubmit,
}) => {
  const [name, setName] = useState('');
  const [selectedParentId, setSelectedParentId] = useState<string>('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    setSelectedParentId(parentSuiteId || '');
  }, [parentSuiteId, isOpen]);

  if (!isOpen) return null;

  const flattenSuites = (nodes: SuiteTreeNode[], depth = 0): Array<{ id: string; name: string; depth: number }> => {
    let result: Array<{ id: string; name: string; depth: number }> = [];
    nodes.forEach((node) => {
      result.push({ id: node.id, name: node.name, depth });
      if (node.children && node.children.length > 0) {
        result = result.concat(flattenSuites(node.children, depth + 1));
      }
    });
    return result;
  };

  const flatSuiteList = flattenSuites(suites);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name) return;

    setIsSubmitting(true);
    try {
      await onSubmit({
        name,
        projectId,
        parentId: selectedParentId || undefined,
      });
      setName('');
      onClose();
    } catch (err) {
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl w-full max-w-md shadow-2xl overflow-hidden animate-scaleUp text-slate-800 dark:text-slate-100">
        <div className="px-6 py-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-900/80">
          <div className="flex items-center space-x-2.5">
            <FolderPlus className="w-5 h-5 text-amber-500 dark:text-amber-400" />
            <h3 className="text-sm font-bold text-slate-800 dark:text-slate-100">Yeni Suite (Klasör) Ekle</h3>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-700 dark:hover:text-white p-1 rounded-lg">
            <X className="w-4 h-4" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div className="space-y-1.5">
            <label className="text-xs font-semibold text-slate-700 dark:text-slate-300">Klasör / Suite Adı</label>
            <input
              type="text"
              required
              placeholder="Örn: Ödeme Adımları & 3D Secure"
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl px-3.5 py-2 text-xs text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-1 focus:ring-amber-500 shadow-sm"
            />
          </div>

          <div className="space-y-1.5">
            <label className="text-xs font-semibold text-slate-700 dark:text-slate-300">
              Bağlı Olduğu Test Planı
            </label>
            <div className="w-full bg-slate-100 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700 rounded-xl px-3.5 py-2 text-xs font-bold text-slate-800 dark:text-slate-200 flex items-center space-x-2">
              <span className="text-amber-500 font-mono">🚀</span>
              <span>{projectKey ? `[${projectKey}] ` : ''}{projectName || 'Aktif Test Planı'}</span>
            </div>
            <p className="text-[10px] text-slate-400">Suite'ler doğrudan Test Planı altında yer almaktadır.</p>
          </div>

          <div className="flex items-center justify-end space-x-3 pt-3">
