                            {tc.title}
                          </div>

                          {tc.description && (
                            <p className="text-[11px] text-slate-500 dark:text-slate-400 line-clamp-1">
                              {tc.description}
                            </p>
                          )}

                          <div className="flex items-center space-x-2 pt-0.5 text-[10px] text-slate-400">
