                      </td>

                      {/* Priority */}
                      <td className="py-3 px-3 text-center">
                        <span
                          className={`text-[9px] px-2 py-0.5 rounded-full border font-mono font-bold inline-block ${getPriorityBadge(
                            tc.priority
